-- RM Workbench corrective architecture revision 2 — PostgreSQL 15+ schema contract.
-- NOT permission to run on any existing/production database.
-- Preconditions: reviewed complete schema inventory; backup + restore rehearsal;
-- verified applied Alembic history; exclusive approved migration window.
-- Run with a fail-on-error client in a disposable database for validation.
-- This transaction does not drop/reset/cast legacy data or guess tenant ownership.
-- New-table name collisions fail closed; only known legacy absence is bootstrapped.
-- UUIDs are generated by application; no extension or credential required.
BEGIN;

-- Reproduce the existing logical baseline only if the complete baseline is absent.
-- A partially present baseline requires reviewed reconciliation, not IF-NOT-EXISTS.
DO $baseline$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM information_schema.tables
 WHERE table_schema='public' AND table_name IN ('clients','holdings','interactions');
 IF n NOT IN (0,3) THEN
   RAISE EXCEPTION 'Partial legacy baseline: inventory and reconcile before upgrade';
 END IF;
 IF n=0 THEN
   CREATE TABLE public.clients (
     id uuid PRIMARY KEY, external_id varchar UNIQUE, name varchar NOT NULL,
     email varchar, phone varchar, aum double precision, currency varchar,
     client_type varchar, region varchar, risk_profile varchar,
     preferences jsonb, is_family_office boolean, family_entities jsonb,
     shariah_compliant boolean, created_at timestamptz, updated_at timestamptz
   );
   CREATE TABLE public.holdings (
     id uuid PRIMARY KEY, client_id uuid REFERENCES public.clients(id),
     symbol varchar NOT NULL, quantity double precision, cost_basis double precision,
     current_value double precision, asset_class varchar, source_kind varchar,
     as_of timestamptz, created_at timestamptz, updated_at timestamptz
   );
   CREATE TABLE public.interactions (
     id uuid PRIMARY KEY, client_id uuid REFERENCES public.clients(id),
     interaction_date timestamptz NOT NULL, interaction_type varchar, summary text,
     preferences_extracted jsonb, action_items jsonb, recording_consent boolean,
     consent_method varchar, source_kind varchar, confidence double precision,
     created_at timestamptz
   );
   CREATE INDEX ix_holdings_client_id ON public.holdings(client_id);
   CREATE INDEX ix_interactions_client_id ON public.interactions(client_id);
 END IF;
 IF to_regclass('public.briefs') IS NULL THEN
   CREATE TABLE public.briefs (
     id uuid PRIMARY KEY, client_id uuid NOT NULL REFERENCES public.clients(id),
     version varchar NOT NULL, sections json NOT NULL, generated_at timestamp NOT NULL,
     approved_by varchar, approved_at timestamp, created_at timestamp
   );
   CREATE INDEX ix_briefs_client_id ON public.briefs(client_id);
 END IF;
END $baseline$;

-- These checks are necessary, NOT a substitute for the full reviewed fingerprint.
DO $preflight$
DECLARE t text; c text; typ text;
BEGIN
 FOREACH t IN ARRAY ARRAY['clients','holdings','interactions','briefs'] LOOP
   SELECT data_type INTO typ FROM information_schema.columns
   WHERE table_schema='public' AND table_name=t AND column_name='id';
   IF typ IS DISTINCT FROM 'uuid' THEN
     RAISE EXCEPTION 'Legacy %.id must be uuid; preserve IDs and review mapping, no cast',t;
   END IF;
   IF NOT EXISTS (
     SELECT 1 FROM pg_constraint con
     JOIN pg_class rel ON rel.oid=con.conrelid
     JOIN pg_namespace ns ON ns.oid=rel.relnamespace
     JOIN pg_attribute a ON a.attrelid=rel.oid AND a.attnum=con.conkey[1]
     WHERE ns.nspname='public' AND rel.relname=t AND con.contype='p'
       AND cardinality(con.conkey)=1 AND a.attname='id'
   ) THEN RAISE EXCEPTION 'Unexpected legacy primary key on %',t; END IF;
 END LOOP;
 FOREACH t IN ARRAY ARRAY['holdings','interactions','briefs'] LOOP
   SELECT data_type INTO typ FROM information_schema.columns
   WHERE table_schema='public' AND table_name=t AND column_name='client_id';
   IF typ IS DISTINCT FROM 'uuid' THEN
     RAISE EXCEPTION 'Legacy %.client_id type drift; no conversion authorized',t;
   END IF;
 END LOOP;
 SELECT data_type INTO typ FROM information_schema.columns
 WHERE table_schema='public' AND table_name='briefs' AND column_name='sections';
 IF typ NOT IN ('json','jsonb') OR typ IS NULL THEN
   RAISE EXCEPTION 'Unexpected legacy briefs.sections type';
 END IF;
 SELECT data_type INTO typ FROM information_schema.columns
 WHERE table_schema='public' AND table_name='briefs' AND column_name='version';
 IF typ NOT IN ('character varying','text') OR typ IS NULL THEN
   RAISE EXCEPTION 'Legacy briefs.version compatibility requires reviewed mapping';
 END IF;
 FOREACH c IN ARRAY ARRAY['tenant_id','workflow_id','meeting_id','artifact_id',
   'artifact_revision_id','revision_no','source_manifest','content_hash','generated_by'] LOOP
   IF EXISTS (SELECT 1 FROM information_schema.columns
     WHERE table_schema='public' AND table_name='briefs' AND column_name=c) THEN
     RAISE EXCEPTION 'Brief contract column % already exists: validate prior revision, do not mask drift',c;
   END IF;
 END LOOP;
END $preflight$;

CREATE TABLE workbench_tenants (
 tenant_id text PRIMARY KEY, environment_kind text NOT NULL
   CHECK(environment_kind IN ('FIXTURE','INSTITUTION_TEST','PRODUCTION')),
 environment_id text NOT NULL, identity_config_ref text,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE books (
 tenant_id text NOT NULL REFERENCES workbench_tenants(tenant_id), book_id text NOT NULL,
 source_version text NOT NULL, entitlement_revision text NOT NULL,
 PRIMARY KEY(tenant_id,book_id)
);
CREATE TABLE client_scope (
 tenant_id text NOT NULL REFERENCES workbench_tenants(tenant_id),
 client_id uuid NOT NULL REFERENCES clients(id), context_revision integer NOT NULL DEFAULT 1
 CHECK(context_revision>0), ownership_source text NOT NULL,
 ownership_version text NOT NULL, verified_at timestamptz NOT NULL,
 PRIMARY KEY(tenant_id,client_id), UNIQUE(client_id)
);
CREATE TABLE client_assignments (
 tenant_id text NOT NULL, book_id text NOT NULL, client_id uuid NOT NULL,
 entitlement_revision text NOT NULL, valid boolean NOT NULL,
 PRIMARY KEY(tenant_id,book_id,client_id),
 FOREIGN KEY(tenant_id,book_id) REFERENCES books(tenant_id,book_id),
 FOREIGN KEY(tenant_id,client_id) REFERENCES client_scope(tenant_id,client_id)
);

CREATE TABLE config_scopes (
 id uuid PRIMARY KEY, tenant_id text NOT NULL REFERENCES workbench_tenants(tenant_id),
 book_id text, jurisdiction text, scope_key text NOT NULL,
 CHECK(scope_key=jsonb_build_array(tenant_id,book_id,jurisdiction)::text),
 UNIQUE(tenant_id,id), UNIQUE(tenant_id,scope_key),
 FOREIGN KEY(tenant_id,book_id) REFERENCES books(tenant_id,book_id)
);
CREATE TABLE configuration_revisions (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, scope_id uuid NOT NULL,
 config_key text NOT NULL, config_class text NOT NULL CHECK(config_class IN
 ('FIELD_MAPPING','RANKING','TEMPLATE','CONSENT','INTEGRATION','GOVERNANCE','METHOD','CATALOG')),
 revision integer NOT NULL CHECK(revision>0), content_hash char(64) NOT NULL,
 status text NOT NULL CHECK(status IN ('UNCONFIGURED','DRAFT','VALIDATED','APPROVED','RETIRED')),
 value jsonb NOT NULL CHECK(jsonb_typeof(value)='object'),
 author text NOT NULL, change_reason text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,id), UNIQUE(tenant_id,scope_id,config_key,revision),
 UNIQUE(tenant_id,scope_id,config_key,id),
 FOREIGN KEY(tenant_id,scope_id) REFERENCES config_scopes(tenant_id,id)
);
CREATE TABLE governance_evidence (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, scope_id uuid NOT NULL,
 evidence_key text NOT NULL, owner text NOT NULL, environment_kind text NOT NULL
 CHECK(environment_kind IN ('FIXTURE','INSTITUTION_TEST','PRODUCTION')),
 environment_id text NOT NULL, reference text NOT NULL, version text NOT NULL,
 status text NOT NULL CHECK(status IN ('PENDING','APPROVED','EXPIRED','BLOCKED')),
 approved_by text, recorded_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz,
 UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,scope_id) REFERENCES config_scopes(tenant_id,id)
);
CREATE TABLE configuration_approvals (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, configuration_id uuid NOT NULL,
 content_hash char(64) NOT NULL, actor text NOT NULL, approved_at timestamptz NOT NULL,
 UNIQUE(tenant_id,id), UNIQUE(tenant_id,configuration_id,id),
 FOREIGN KEY(tenant_id,configuration_id) REFERENCES configuration_revisions(tenant_id,id)
);
CREATE TABLE configuration_approval_evidence (
 tenant_id text NOT NULL, approval_id uuid NOT NULL, evidence_id uuid NOT NULL,
 PRIMARY KEY(tenant_id,approval_id,evidence_id),
 FOREIGN KEY(tenant_id,approval_id) REFERENCES configuration_approvals(tenant_id,id),
 FOREIGN KEY(tenant_id,evidence_id) REFERENCES governance_evidence(tenant_id,id)
);
CREATE TABLE configuration_activations (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, scope_id uuid NOT NULL,
 config_key text NOT NULL, configuration_id uuid NOT NULL, approval_id uuid NOT NULL,
 actor text NOT NULL, reason text NOT NULL, activated_at timestamptz NOT NULL,
 UNIQUE(tenant_id,id), UNIQUE(tenant_id,scope_id,config_key,id),
 FOREIGN KEY(tenant_id,scope_id,config_key,configuration_id)
 REFERENCES configuration_revisions(tenant_id,scope_id,config_key,id),
 FOREIGN KEY(tenant_id,configuration_id,approval_id)
 REFERENCES configuration_approvals(tenant_id,configuration_id,id)
);
CREATE TABLE active_configurations (
 tenant_id text NOT NULL, scope_id uuid NOT NULL, config_key text NOT NULL,
 activation_id uuid NOT NULL, row_version integer NOT NULL CHECK(row_version>0),
 PRIMARY KEY(tenant_id,scope_id,config_key),
 FOREIGN KEY(tenant_id,scope_id,config_key,activation_id)
 REFERENCES configuration_activations(tenant_id,scope_id,config_key,id)
);
CREATE TABLE capability_controls (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, scope_id uuid NOT NULL,
 capability_key text NOT NULL, enabled boolean NOT NULL DEFAULT false,
 revision integer NOT NULL CHECK(revision>0), cohort_refs jsonb NOT NULL DEFAULT '[]'
 CHECK(jsonb_typeof(cohort_refs)='array'), reason text NOT NULL, actor text NOT NULL,
 changed_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,id), UNIQUE(tenant_id,scope_id,capability_key,revision),
 UNIQUE(tenant_id,scope_id,capability_key,id),
 FOREIGN KEY(tenant_id,scope_id) REFERENCES config_scopes(tenant_id,id)
);
CREATE TABLE capability_current_controls (
 tenant_id text NOT NULL, scope_id uuid NOT NULL, capability_key text NOT NULL,
 control_id uuid NOT NULL, row_version integer NOT NULL CHECK(row_version>0),
 PRIMARY KEY(tenant_id,scope_id,capability_key),
 FOREIGN KEY(tenant_id,scope_id,capability_key,control_id)
 REFERENCES capability_controls(tenant_id,scope_id,capability_key,id)
);
CREATE TABLE capability_control_evidence (
 tenant_id text NOT NULL, control_id uuid NOT NULL, evidence_id uuid NOT NULL,
 PRIMARY KEY(tenant_id,control_id,evidence_id),
 FOREIGN KEY(tenant_id,control_id) REFERENCES capability_controls(tenant_id,id),
 FOREIGN KEY(tenant_id,evidence_id) REFERENCES governance_evidence(tenant_id,id)
);

CREATE TABLE calendar_events (
 id uuid PRIMARY KEY, tenant_id text NOT NULL REFERENCES workbench_tenants(tenant_id),
 actor_subject text NOT NULL, provider_key text NOT NULL, provider_event_id text NOT NULL,
 provider_version text NOT NULL, payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),
 status text NOT NULL CHECK(status IN ('ACTIVE','CANCELED','INELIGIBLE')),
 match_state text NOT NULL CHECK(match_state IN ('VERIFIED','AMBIGUOUS','UNMATCHED','CONFLICT')),
 retrieved_at timestamptz NOT NULL, UNIQUE(tenant_id,id),
 UNIQUE(tenant_id,actor_subject,provider_key,provider_event_id,provider_version)
);
CREATE TABLE meetings (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL,
 calendar_event_id uuid, event_version text,
 resolution text NOT NULL CHECK(resolution IN ('VERIFIED','RM_CONFIRMED','CONFLICT')),
 title text, starts_at timestamptz, ends_at timestamptz,
 row_version integer NOT NULL DEFAULT 1 CHECK(row_version>0),
 resolved_by text NOT NULL, resolved_at timestamptz NOT NULL,
 UNIQUE(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id) REFERENCES client_scope(tenant_id,client_id),
 FOREIGN KEY(tenant_id,calendar_event_id) REFERENCES calendar_events(tenant_id,id),
 CHECK(ends_at IS NULL OR starts_at IS NULL OR ends_at>=starts_at)
);
CREATE TABLE workflows (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL, meeting_id uuid,
 workflow_type text NOT NULL CHECK(workflow_type IN
 ('MEETING_PREP','MEETING_FOLLOWUP','OUTREACH','PRODUCT_SEARCH','SHARIAH_REVIEW','HOUSEHOLD_REVIEW')),
 status text NOT NULL CHECK(status IN
 ('NOT_STARTED','RUNNING','NEEDS_REVIEW','PAUSED','BLOCKED','UNAVAILABLE','FAILED','ABANDONED','COMPLETED')),
 current_stage text, row_version integer NOT NULL DEFAULT 1 CHECK(row_version>0),
 context_revision integer NOT NULL CHECK(context_revision>0),
 entry_point text NOT NULL, task_context text, created_by text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,client_id,id), UNIQUE(tenant_id,client_id,id,meeting_id),
 FOREIGN KEY(tenant_id,client_id) REFERENCES client_scope(tenant_id,client_id),
 FOREIGN KEY(tenant_id,client_id,meeting_id) REFERENCES meetings(tenant_id,client_id,id)
);
CREATE INDEX ix_workflow_resume ON workflows(tenant_id,created_by,status,updated_at DESC);
CREATE TABLE skill_versions (
 tenant_id text NOT NULL REFERENCES workbench_tenants(tenant_id),
 skill_id text NOT NULL, version text NOT NULL, handler_key text NOT NULL,
 descriptor jsonb NOT NULL CHECK(jsonb_typeof(descriptor)='object'),
 content_hash char(64) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(tenant_id,skill_id,version)
);
CREATE TABLE stage_runs (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL, workflow_id uuid NOT NULL,
 stage_key text NOT NULL, stage_version integer NOT NULL CHECK(stage_version>0),
 status text NOT NULL CHECK(status IN ('PENDING','RUNNING','NEEDS_REVIEW','APPROVED','BLOCKED','FAILED','SKIPPED','COMPLETED')),
 skill_id text NOT NULL, skill_version text NOT NULL, context_revision integer NOT NULL,
 manual_intervention boolean NOT NULL DEFAULT false, error_code text,
 lease_token uuid, lease_until timestamptz, started_at timestamptz, completed_at timestamptz,
 UNIQUE(tenant_id,client_id,id), UNIQUE(tenant_id,workflow_id,stage_key,stage_version),
 FOREIGN KEY(tenant_id,client_id,workflow_id) REFERENCES workflows(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,skill_id,skill_version) REFERENCES skill_versions(tenant_id,skill_id,version)
);
CREATE INDEX ix_stage_claim ON stage_runs(status,lease_until) WHERE status IN ('PENDING','RUNNING');

CREATE TABLE artifact_lineages (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL, workflow_id uuid NOT NULL,
 meeting_id uuid, kind text NOT NULL CHECK(kind IN
 ('BRIEF','TRANSCRIPT','EXTRACTION','NOTES','CRM_CHANGE','TASK','MEMORY_PROPOSAL','MESSAGE','TICKET_PREFILL',
 'PRODUCT_INTERPRETATION','PRODUCT_SEARCH','PRODUCT_COMPARISON','ASSESSMENT','SHARIAH_SCREEN',
 'SHARIAH_ESTIMATE','SHARIAH_PACK','STRUCTURE_PROPOSAL','CONSOLIDATION','ATTENDEE_PACK',
 'FAMILY_SCENARIO','CAPITAL_NOTICE','LIQUIDITY_FORECAST')),
 current_revision_id uuid, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id,workflow_id) REFERENCES workflows(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id,meeting_id) REFERENCES meetings(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id,workflow_id,meeting_id)
 REFERENCES workflows(tenant_id,client_id,id,meeting_id)
);
CREATE INDEX ix_artifact_client_kind ON artifact_lineages(tenant_id,client_id,kind,created_at DESC);
CREATE TABLE artifact_revisions (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL, artifact_id uuid NOT NULL,
 version integer NOT NULL CHECK(version>0), content_hash char(64) NOT NULL,
 payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),
 environment_kind text NOT NULL CHECK(environment_kind IN ('FIXTURE','INSTITUTION_TEST','PRODUCTION')),
 environment_id text NOT NULL, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,client_id,id), UNIQUE(tenant_id,client_id,artifact_id,id),
 UNIQUE(tenant_id,artifact_id,version),
 FOREIGN KEY(tenant_id,client_id,artifact_id) REFERENCES artifact_lineages(tenant_id,client_id,id)
);
ALTER TABLE artifact_lineages ADD CONSTRAINT fk_artifact_current_revision
 FOREIGN KEY(tenant_id,client_id,id,current_revision_id)
 REFERENCES artifact_revisions(tenant_id,client_id,artifact_id,id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE artifact_items (
 tenant_id text NOT NULL, client_id uuid NOT NULL, revision_id uuid NOT NULL,
 item_key text NOT NULL, item_hash char(64) NOT NULL,
 status text NOT NULL CHECK(status IN ('UNREVIEWED','NEEDS_REVIEW','APPROVED','REJECTED','BLOCKED')),
 PRIMARY KEY(tenant_id,client_id,revision_id,item_key),
 UNIQUE(tenant_id,client_id,revision_id,item_key,item_hash),
 FOREIGN KEY(tenant_id,client_id,revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id)
);
CREATE TABLE artifact_dependencies (
 tenant_id text NOT NULL, client_id uuid NOT NULL, dependent_revision_id uuid NOT NULL,
 basis_revision_id uuid NOT NULL, basis_hash char(64) NOT NULL,
 PRIMARY KEY(tenant_id,client_id,dependent_revision_id,basis_revision_id),
 FOREIGN KEY(tenant_id,client_id,dependent_revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id,basis_revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id),
 CHECK(dependent_revision_id<>basis_revision_id)
);
CREATE TABLE revision_config_dependencies (
 tenant_id text NOT NULL, client_id uuid NOT NULL, revision_id uuid NOT NULL,
 configuration_id uuid NOT NULL, content_hash char(64) NOT NULL,
 PRIMARY KEY(tenant_id,client_id,revision_id,configuration_id),
 FOREIGN KEY(tenant_id,client_id,revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,configuration_id) REFERENCES configuration_revisions(tenant_id,id)
);
CREATE TABLE stage_artifact_refs (
 tenant_id text NOT NULL, client_id uuid NOT NULL, run_id uuid NOT NULL,
 revision_id uuid NOT NULL, direction text NOT NULL CHECK(direction IN ('INPUT','OUTPUT')),
 PRIMARY KEY(tenant_id,client_id,run_id,revision_id,direction),
 FOREIGN KEY(tenant_id,client_id,run_id) REFERENCES stage_runs(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id,revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id)
);

-- Existing brief columns remain untouched. Nullable columns keep legacy rows valid.
ALTER TABLE briefs ADD COLUMN tenant_id text;
ALTER TABLE briefs ADD COLUMN workflow_id uuid;
ALTER TABLE briefs ADD COLUMN meeting_id uuid;
ALTER TABLE briefs ADD COLUMN artifact_id uuid;
ALTER TABLE briefs ADD COLUMN artifact_revision_id uuid;
ALTER TABLE briefs ADD COLUMN revision_no integer;
ALTER TABLE briefs ADD COLUMN source_manifest jsonb;
ALTER TABLE briefs ADD COLUMN content_hash char(64);
ALTER TABLE briefs ADD COLUMN generated_by text;
ALTER TABLE briefs ADD CONSTRAINT ck_brief_new_link CHECK (
 (tenant_id IS NULL AND workflow_id IS NULL AND meeting_id IS NULL AND artifact_id IS NULL
 AND artifact_revision_id IS NULL AND revision_no IS NULL AND source_manifest IS NULL
 AND content_hash IS NULL AND generated_by IS NULL)
 OR (tenant_id IS NOT NULL AND workflow_id IS NOT NULL AND artifact_id IS NOT NULL
 AND artifact_revision_id IS NOT NULL AND revision_no>0 AND source_manifest IS NOT NULL
 AND content_hash IS NOT NULL AND generated_by IS NOT NULL)
);
ALTER TABLE briefs ADD CONSTRAINT uq_brief_revision UNIQUE(tenant_id,artifact_revision_id);
ALTER TABLE briefs ADD CONSTRAINT uq_brief_lineage_version UNIQUE(tenant_id,artifact_id,revision_no);
ALTER TABLE briefs ADD CONSTRAINT fk_brief_scope FOREIGN KEY(tenant_id,client_id)
 REFERENCES client_scope(tenant_id,client_id);
ALTER TABLE briefs ADD CONSTRAINT fk_brief_workflow FOREIGN KEY(tenant_id,client_id,workflow_id)
 REFERENCES workflows(tenant_id,client_id,id);
ALTER TABLE briefs ADD CONSTRAINT fk_brief_meeting FOREIGN KEY(tenant_id,client_id,meeting_id)
 REFERENCES meetings(tenant_id,client_id,id);
ALTER TABLE briefs ADD CONSTRAINT fk_brief_workflow_meeting FOREIGN KEY(tenant_id,client_id,workflow_id,meeting_id)
 REFERENCES workflows(tenant_id,client_id,id,meeting_id);
ALTER TABLE briefs ADD CONSTRAINT fk_brief_artifact FOREIGN KEY(tenant_id,client_id,artifact_id,artifact_revision_id)
 REFERENCES artifact_revisions(tenant_id,client_id,artifact_id,id);
CREATE INDEX ix_brief_workflow_version ON briefs(tenant_id,workflow_id,revision_no DESC);

CREATE TABLE source_evidence (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL,
 environment_kind text NOT NULL CHECK(environment_kind IN ('FIXTURE','INSTITUTION_TEST','PRODUCTION')),
 environment_id text NOT NULL,
 availability text NOT NULL CHECK(availability IN ('AVAILABLE','STALE','UNAVAILABLE','CONFLICT')),
 origin text NOT NULL CHECK(origin IN ('RECORDED','DERIVED','RM_ENTERED')),
 system_key text, record_id text, record_version text, source_as_of timestamptz,
 retrieved_at timestamptz, authoritative_owner text, freshness_configuration_id uuid,
 live_response boolean NOT NULL DEFAULT false, adapter_receipt_id text,
 confidence numeric CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1),
 evidence_location jsonb, limitations jsonb NOT NULL DEFAULT '[]',
 UNIQUE(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id) REFERENCES client_scope(tenant_id,client_id),
 FOREIGN KEY(tenant_id,freshness_configuration_id) REFERENCES configuration_revisions(tenant_id,id),
 CHECK(NOT live_response OR (environment_kind<>'FIXTURE' AND adapter_receipt_id IS NOT NULL
 AND system_key IS NOT NULL AND record_id IS NOT NULL AND retrieved_at IS NOT NULL))
);
CREATE TABLE revision_sources (
 tenant_id text NOT NULL, client_id uuid NOT NULL, revision_id uuid NOT NULL,
 source_id uuid NOT NULL, claim_path text NOT NULL,
 PRIMARY KEY(tenant_id,client_id,revision_id,source_id,claim_path),
 FOREIGN KEY(tenant_id,client_id,revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id,source_id) REFERENCES source_evidence(tenant_id,client_id,id)
);
CREATE TABLE source_derivations (
 tenant_id text NOT NULL, client_id uuid NOT NULL, derived_source_id uuid NOT NULL,
 input_source_id uuid NOT NULL, method_ref text NOT NULL,
 PRIMARY KEY(tenant_id,client_id,derived_source_id,input_source_id),
 FOREIGN KEY(tenant_id,client_id,derived_source_id) REFERENCES source_evidence(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id,input_source_id) REFERENCES source_evidence(tenant_id,client_id,id),
 CHECK(derived_source_id<>input_source_id)
);
CREATE TABLE review_decisions (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL, revision_id uuid NOT NULL,
 scope text NOT NULL CHECK(scope IN ('ARTIFACT','ITEM')), item_key text, item_hash char(64) NOT NULL,
 decision text NOT NULL CHECK(decision IN ('APPROVED','REJECTED')),
 actor text NOT NULL, reason jsonb, recorded_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id,revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id,revision_id,item_key,item_hash)
 REFERENCES artifact_items(tenant_id,client_id,revision_id,item_key,item_hash),
 CHECK((scope='ARTIFACT' AND item_key IS NULL) OR (scope='ITEM' AND item_key IS NOT NULL))
);
CREATE INDEX ix_review_revision ON review_decisions(tenant_id,client_id,revision_id,recorded_at DESC);
CREATE TABLE feedback (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL,
 revision_id uuid NOT NULL, item_key text, feedback_type text NOT NULL
 CHECK(feedback_type IN ('HELPFUL','NOT_HELPFUL','UNSUPPORTED_FACT')),
 reason jsonb NOT NULL, comment text, actor text NOT NULL, recorded_at timestamptz NOT NULL,
 FOREIGN KEY(tenant_id,client_id,revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id)
);
CREATE TABLE content_suppressions (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL, revision_id uuid NOT NULL,
 item_key text NOT NULL, reason jsonb NOT NULL, actor text NOT NULL,
 retention_configuration_id uuid NOT NULL, suppressed_at timestamptz NOT NULL,
 FOREIGN KEY(tenant_id,client_id,revision_id,item_key) REFERENCES artifact_items(tenant_id,client_id,revision_id,item_key),
 FOREIGN KEY(tenant_id,retention_configuration_id) REFERENCES configuration_revisions(tenant_id,id)
);

CREATE TABLE attachments (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL, workflow_id uuid,
 meeting_id uuid, filename text NOT NULL, mime_type text NOT NULL, byte_size bigint NOT NULL CHECK(byte_size>0),
 checksum char(64) NOT NULL, policy_configuration_id uuid NOT NULL, object_ref text,
 status text NOT NULL CHECK(status IN ('UPLOADING','UPLOADED','SCANNING','READY','REJECTED')),
 created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id) REFERENCES client_scope(tenant_id,client_id),
 FOREIGN KEY(tenant_id,client_id,workflow_id) REFERENCES workflows(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id,meeting_id) REFERENCES meetings(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,policy_configuration_id) REFERENCES configuration_revisions(tenant_id,id),
 CHECK(workflow_id IS NOT NULL OR meeting_id IS NOT NULL)
);
CREATE TABLE consent_records (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL, meeting_id uuid NOT NULL,
 policy_configuration_id uuid NOT NULL, jurisdiction text NOT NULL, platform text NOT NULL,
 language text NOT NULL, method text NOT NULL, participant_refs jsonb NOT NULL
 CHECK(jsonb_typeof(participant_refs)='array'),
 state text NOT NULL CHECK(state IN ('ACCEPTED','DECLINED','WITHDRAWN')),
 actor text NOT NULL, recorded_at timestamptz NOT NULL, withdrawn_at timestamptz,
 row_version integer NOT NULL DEFAULT 1 CHECK(row_version>0),
 UNIQUE(tenant_id,client_id,id), UNIQUE(tenant_id,client_id,meeting_id,id),
 FOREIGN KEY(tenant_id,client_id,meeting_id) REFERENCES meetings(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,policy_configuration_id) REFERENCES configuration_revisions(tenant_id,id)
);
CREATE TABLE capture_sessions (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL, meeting_id uuid NOT NULL,
 consent_id uuid NOT NULL, provider_key text NOT NULL, provider_ref text,
 status text NOT NULL CHECK(status IN ('STARTING','RECORDING','PAUSED','STOPPING','STOPPED','PROCESSING','PARTIAL','COMPLETE','FAILED')),
 row_version integer NOT NULL DEFAULT 1, last_confirmed_audio_ms bigint,
 last_confirmed_transcript_ms bigint, lease_valid_until timestamptz,
 lease_revoked boolean NOT NULL DEFAULT false, error_code text,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id,meeting_id,consent_id)
 REFERENCES consent_records(tenant_id,client_id,meeting_id,id)
);
CREATE UNIQUE INDEX uq_capture_active_meeting ON capture_sessions(tenant_id,meeting_id)
 WHERE status IN ('STARTING','RECORDING','PAUSED','STOPPING');

CREATE TABLE action_previews (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL, revision_id uuid NOT NULL,
 action_class text NOT NULL CHECK(action_class IN ('CRM_WRITE','TASK_WRITE','MEMORY_WRITE','CLIENT_SEND','TICKET_PREFILL')),
 preview_hash char(64) NOT NULL, request_hash char(64) NOT NULL,
 approved_request jsonb NOT NULL CHECK(jsonb_typeof(approved_request)='object'),
 provider_key text NOT NULL, destination_ref text NOT NULL,
 environment_kind text NOT NULL CHECK(environment_kind IN ('FIXTURE','INSTITUTION_TEST','PRODUCTION')),
 environment_id text NOT NULL, context_revision integer NOT NULL CHECK(context_revision>0),
 dependency_manifest jsonb NOT NULL CHECK(jsonb_typeof(dependency_manifest)='object'),
 status text NOT NULL CHECK(status IN ('VALID','INVALIDATED','REVOKED')),
 created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,client_id,id),
 UNIQUE(tenant_id,client_id,revision_id,action_class,provider_key,destination_ref,request_hash),
 FOREIGN KEY(tenant_id,client_id,revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id)
);
CREATE TABLE action_authorizations (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL, preview_id uuid NOT NULL,
 preview_hash char(64) NOT NULL, action_class text NOT NULL
 CHECK(action_class IN ('CRM_WRITE','TASK_WRITE','MEMORY_WRITE','CLIENT_SEND','TICKET_PREFILL')),
 actor text NOT NULL, authorized_at timestamptz NOT NULL,
 status text NOT NULL CHECK(status IN ('VALID','INVALIDATED','REVOKED')),
 invalidated_at timestamptz, invalidation_code text,
 UNIQUE(tenant_id,client_id,id), UNIQUE(tenant_id,preview_id),
 FOREIGN KEY(tenant_id,client_id,preview_id) REFERENCES action_previews(tenant_id,client_id,id)
);
CREATE TABLE outbox_actions (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL, authorization_id uuid NOT NULL,
 provider_operation_key text NOT NULL, status text NOT NULL CHECK(status IN
 ('PENDING','SENDING','SUCCEEDED','FAILED_SAFE','UNKNOWN','RECONCILE_REQUIRED','CANCELED_BEFORE_DISPATCH')),
 provider_ref text, provider_state text CHECK(provider_state IN
 ('ACCEPTED','SCHEDULED','DELIVERED','WRITTEN','PREFILLED','NOT_ACCEPTED','UNKNOWN')),
 lease_token uuid, lease_until timestamptz, attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count>=0),
 submitted_at timestamptz, confirmed_at timestamptz, readback_at timestamptz,
 last_error_code text, reconciliation_owner text,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,client_id,id), UNIQUE(tenant_id,authorization_id),
 UNIQUE(tenant_id,provider_operation_key),
 FOREIGN KEY(tenant_id,client_id,authorization_id) REFERENCES action_authorizations(tenant_id,client_id,id)
);
CREATE INDEX ix_outbox_claim ON outbox_actions(status,lease_until,created_at)
 WHERE status IN ('PENDING','SENDING','UNKNOWN','RECONCILE_REQUIRED');
CREATE TABLE outbox_attempts (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL, action_id uuid NOT NULL,
 attempt_no integer NOT NULL CHECK(attempt_no>0), mode text NOT NULL CHECK(mode IN ('DISPATCH','READBACK')),
 lease_token uuid NOT NULL, status text NOT NULL CHECK(status IN ('STARTED','CONFIRMED','NOT_ACCEPTED','UNKNOWN')),
 request_hash char(64) NOT NULL, receipt_ref text, error_code text,
 started_at timestamptz NOT NULL, ended_at timestamptz,
 UNIQUE(tenant_id,action_id,attempt_no), UNIQUE(tenant_id,client_id,action_id,id),
 FOREIGN KEY(tenant_id,client_id,action_id) REFERENCES outbox_actions(tenant_id,client_id,id)
);
CREATE TABLE action_retry_authorizations (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL, action_id uuid NOT NULL,
 not_accepted_attempt_id uuid NOT NULL,
 actor text NOT NULL, authorized_at timestamptz NOT NULL, reason text NOT NULL,
 FOREIGN KEY(tenant_id,client_id,action_id) REFERENCES outbox_actions(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id,action_id,not_accepted_attempt_id)
 REFERENCES outbox_attempts(tenant_id,client_id,action_id,id)
);
CREATE TABLE idempotency_requests (
 id uuid PRIMARY KEY, tenant_id text NOT NULL REFERENCES workbench_tenants(tenant_id),
 actor text NOT NULL, method text NOT NULL, path text NOT NULL, idempotency_key uuid NOT NULL,
 request_hash char(64) NOT NULL, status text NOT NULL CHECK(status IN ('IN_PROGRESS','COMPLETED')),
 response_status integer, response_body jsonb, resource_ref text,
 created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz,
 UNIQUE(tenant_id,actor,method,path,idempotency_key)
);

CREATE TABLE client_memory_entries (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL,
 memory_key text NOT NULL, version integer NOT NULL CHECK(version>0), value jsonb NOT NULL,
 state text NOT NULL CHECK(state IN ('CONFIRMED','CONFLICT','SUPERSEDED')),
 source_revision_id uuid NOT NULL, authorization_id uuid NOT NULL,
 confirmed_by text NOT NULL, confirmed_at timestamptz NOT NULL,
 UNIQUE(tenant_id,client_id,id), UNIQUE(tenant_id,client_id,memory_key,version),
 FOREIGN KEY(tenant_id,client_id) REFERENCES client_scope(tenant_id,client_id),
 FOREIGN KEY(tenant_id,client_id,source_revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id,authorization_id) REFERENCES action_authorizations(tenant_id,client_id,id)
);
CREATE INDEX ix_memory_context ON client_memory_entries(tenant_id,client_id,memory_key,version DESC);

CREATE TABLE priority_evaluations (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, book_id text NOT NULL, local_date date NOT NULL,
 timezone text NOT NULL, policy_configuration_id uuid NOT NULL,
 status text NOT NULL CHECK(status IN ('CURRENT','STALE','FAILED')),
 criteria_summary text NOT NULL, evaluated_at timestamptz NOT NULL,
 environment_kind text NOT NULL CHECK(environment_kind IN ('FIXTURE','INSTITUTION_TEST','PRODUCTION')),
 environment_id text NOT NULL, created_by text NOT NULL,
 UNIQUE(tenant_id,book_id,id),
 FOREIGN KEY(tenant_id,book_id) REFERENCES books(tenant_id,book_id),
 FOREIGN KEY(tenant_id,policy_configuration_id) REFERENCES configuration_revisions(tenant_id,id)
);
CREATE INDEX ix_priority_latest ON priority_evaluations(tenant_id,book_id,local_date,evaluated_at DESC);
CREATE TABLE priority_items (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, book_id text NOT NULL,
 evaluation_id uuid NOT NULL, client_id uuid NOT NULL, rank integer NOT NULL CHECK(rank BETWEEN 1 AND 10),
 reasons jsonb NOT NULL CHECK(jsonb_typeof(reasons)='array'), rank_change_explanation text,
 last_updated_at timestamptz NOT NULL,
 UNIQUE(tenant_id,evaluation_id,client_id), UNIQUE(tenant_id,evaluation_id,rank),
 UNIQUE(tenant_id,book_id,evaluation_id,client_id),
 FOREIGN KEY(tenant_id,book_id,evaluation_id) REFERENCES priority_evaluations(tenant_id,book_id,id),
 FOREIGN KEY(tenant_id,book_id,client_id) REFERENCES client_assignments(tenant_id,book_id,client_id)
);
CREATE TABLE priority_controls (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, book_id text NOT NULL, client_id uuid NOT NULL,
 evaluation_id uuid NOT NULL, reason_key text NOT NULL, reason_hash char(64) NOT NULL,
 control_type text NOT NULL CHECK(control_type IN ('SNOOZE','DISMISS','PIN')),
 until_at timestamptz, pinned boolean, reason jsonb, policy_configuration_id uuid NOT NULL,
 actor text NOT NULL, recorded_at timestamptz NOT NULL, row_version integer NOT NULL CHECK(row_version>0),
 FOREIGN KEY(tenant_id,book_id,evaluation_id,client_id)
 REFERENCES priority_items(tenant_id,book_id,evaluation_id,client_id),
 FOREIGN KEY(tenant_id,policy_configuration_id) REFERENCES configuration_revisions(tenant_id,id),
 CHECK((control_type='SNOOZE' AND until_at IS NOT NULL AND until_at>recorded_at)
 OR (control_type='DISMISS' AND reason IS NOT NULL) OR (control_type='PIN' AND pinned IS NOT NULL))
);
CREATE TABLE contact_outcomes (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, book_id text NOT NULL, client_id uuid NOT NULL,
 evaluation_id uuid NOT NULL, reason_key text NOT NULL, reason_hash char(64) NOT NULL,
 outcome text NOT NULL CHECK(outcome IN ('CONTACTED','MEETING_BOOKED','NO_RESPONSE','NOT_RELEVANT')),
 occurred_at timestamptz NOT NULL, recorded_at timestamptz NOT NULL,
 note text, meeting_id uuid, evidence_refs jsonb NOT NULL DEFAULT '[]',
 meaningful_touchpoint text NOT NULL CHECK(meaningful_touchpoint IN ('CONFIRMED','NOT_CONFIRMED','UNCONFIGURED')),
 actor text NOT NULL,
 FOREIGN KEY(tenant_id,book_id,evaluation_id,client_id)
 REFERENCES priority_items(tenant_id,book_id,evaluation_id,client_id),
 FOREIGN KEY(tenant_id,client_id,meeting_id) REFERENCES meetings(tenant_id,client_id,id),
 CHECK(occurred_at<=recorded_at)
);

CREATE TABLE candidate_selections (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL,
 search_revision_id uuid NOT NULL, product_id text NOT NULL, product_version text NOT NULL,
 actor text NOT NULL, selected_at timestamptz NOT NULL,
 FOREIGN KEY(tenant_id,client_id,search_revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id)
);
CREATE TABLE suitability_overrides (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL,
 assessment_revision_id uuid NOT NULL, factor_keys jsonb NOT NULL,
 reason jsonb NOT NULL, rationale text NOT NULL CHECK(length(trim(rationale))>0),
 policy_configuration_id uuid NOT NULL, original_rating text NOT NULL
 CHECK(original_rating IN ('GREEN','YELLOW','RED')),
 actor text NOT NULL, recorded_at timestamptz NOT NULL,
 FOREIGN KEY(tenant_id,client_id,assessment_revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,policy_configuration_id) REFERENCES configuration_revisions(tenant_id,id)
);

CREATE TABLE households (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL,
 version integer NOT NULL CHECK(version>0), entitlement_revision text NOT NULL,
 UNIQUE(tenant_id,id), UNIQUE(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id) REFERENCES client_scope(tenant_id,client_id)
);
CREATE TABLE graph_nodes (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, household_id uuid NOT NULL,
 linked_client_id uuid, type_code text NOT NULL, name text NOT NULL,
 version integer NOT NULL CHECK(version>0), evidence_refs jsonb NOT NULL,
 confirmed_from_revision_id uuid NOT NULL, anchor_client_id uuid NOT NULL,
 confirmed_by text NOT NULL, confirmed_at timestamptz NOT NULL,
 UNIQUE(tenant_id,household_id,id),
 FOREIGN KEY(tenant_id,anchor_client_id,household_id) REFERENCES households(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,linked_client_id) REFERENCES client_scope(tenant_id,client_id),
 FOREIGN KEY(tenant_id,anchor_client_id,confirmed_from_revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id)
);
CREATE TABLE graph_edges (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, household_id uuid NOT NULL,
 from_node_id uuid NOT NULL, to_node_id uuid NOT NULL, type_code text NOT NULL,
 version integer NOT NULL CHECK(version>0), evidence_refs jsonb NOT NULL,
 confirmed_by text NOT NULL, confirmed_at timestamptz NOT NULL,
 UNIQUE(tenant_id,household_id,id),
 FOREIGN KEY(tenant_id,household_id,from_node_id) REFERENCES graph_nodes(tenant_id,household_id,id),
 FOREIGN KEY(tenant_id,household_id,to_node_id) REFERENCES graph_nodes(tenant_id,household_id,id),
 CHECK(from_node_id<>to_node_id)
);
CREATE TABLE node_entitlements (
 tenant_id text NOT NULL, household_id uuid NOT NULL, node_id uuid NOT NULL,
 subject_ref text NOT NULL, permission text NOT NULL,
 entitlement_revision text NOT NULL, allowed boolean NOT NULL, verified_at timestamptz NOT NULL,
 PRIMARY KEY(tenant_id,household_id,node_id,subject_ref,permission),
 FOREIGN KEY(tenant_id,household_id,node_id) REFERENCES graph_nodes(tenant_id,household_id,id)
);
CREATE TABLE advisor_confirmations (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL, revision_id uuid NOT NULL,
 advisor_ref text NOT NULL, confirmation_source_id uuid NOT NULL,
 confirmed_on date NOT NULL, recorded_by text NOT NULL, recorded_at timestamptz NOT NULL,
 FOREIGN KEY(tenant_id,client_id,revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id,confirmation_source_id) REFERENCES source_evidence(tenant_id,client_id,id)
);
CREATE TABLE artifact_finalizations (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL, revision_id uuid NOT NULL,
 archive_ref text NOT NULL, archive_hash char(64) NOT NULL, archived_at timestamptz NOT NULL,
 actor text NOT NULL, review_ids jsonb NOT NULL,
 UNIQUE(tenant_id,revision_id),
 FOREIGN KEY(tenant_id,client_id,revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id)
);
CREATE TABLE forecast_actuals (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, client_id uuid NOT NULL,
 forecast_revision_id uuid NOT NULL, notice_revision_id uuid NOT NULL,
 actual_amount numeric NOT NULL CHECK(actual_amount>0), currency text NOT NULL, actual_date date NOT NULL,
 evidence_refs jsonb NOT NULL, actor text NOT NULL, recorded_at timestamptz NOT NULL,
 FOREIGN KEY(tenant_id,client_id,forecast_revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id,notice_revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id)
);

CREATE TABLE audit_events (
 id uuid PRIMARY KEY, tenant_id text NOT NULL REFERENCES workbench_tenants(tenant_id),
 client_id uuid, workflow_id uuid, revision_id uuid,
 actor text NOT NULL, action text NOT NULL, resource_type text NOT NULL, resource_id text NOT NULL,
 correlation_id uuid NOT NULL, occurred_at timestamptz NOT NULL,
 previous_hash char(64), event_hash char(64) NOT NULL,
 safe_details jsonb NOT NULL CHECK(jsonb_typeof(safe_details)='object'),
 UNIQUE(tenant_id,id), UNIQUE(tenant_id,event_hash),
 FOREIGN KEY(tenant_id,client_id) REFERENCES client_scope(tenant_id,client_id),
 FOREIGN KEY(tenant_id,client_id,workflow_id) REFERENCES workflows(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id,revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id),
 CHECK((workflow_id IS NULL AND revision_id IS NULL) OR client_id IS NOT NULL)
);
CREATE TABLE audit_chain_heads (
 tenant_id text PRIMARY KEY REFERENCES workbench_tenants(tenant_id),
 last_event_id uuid NOT NULL, last_event_hash char(64) NOT NULL,
 FOREIGN KEY(tenant_id,last_event_id) REFERENCES audit_events(tenant_id,id)
);
CREATE INDEX ix_audit_resource ON audit_events(tenant_id,resource_type,resource_id,occurred_at DESC);
CREATE TABLE telemetry_events (
 id uuid PRIMARY KEY, tenant_id text NOT NULL REFERENCES workbench_tenants(tenant_id),
 book_id text, client_id uuid, workflow_id uuid, revision_id uuid,
 environment_kind text NOT NULL CHECK(environment_kind IN ('FIXTURE','INSTITUTION_TEST','PRODUCTION')),
 environment_id text NOT NULL, event_name text NOT NULL, actor_safe_id text NOT NULL,
 correlation_id uuid NOT NULL, occurred_at timestamptz NOT NULL,
 version_tags jsonb NOT NULL CHECK(jsonb_typeof(version_tags)='object'),
 measures jsonb NOT NULL CHECK(jsonb_typeof(measures)='object'),
 FOREIGN KEY(tenant_id,book_id) REFERENCES books(tenant_id,book_id),
 FOREIGN KEY(tenant_id,client_id) REFERENCES client_scope(tenant_id,client_id),
 FOREIGN KEY(tenant_id,client_id,workflow_id) REFERENCES workflows(tenant_id,client_id,id),
 FOREIGN KEY(tenant_id,client_id,revision_id) REFERENCES artifact_revisions(tenant_id,client_id,id),
 CHECK((workflow_id IS NULL AND revision_id IS NULL) OR client_id IS NOT NULL)
);
CREATE INDEX ix_telemetry_measure ON telemetry_events(tenant_id,environment_kind,event_name,occurred_at);
CREATE TABLE metric_snapshots (
 id uuid PRIMARY KEY, tenant_id text NOT NULL, scope_id uuid NOT NULL,
 metric_key text NOT NULL, definition_configuration_id uuid,
 from_at timestamptz NOT NULL, to_at timestamptz NOT NULL CHECK(to_at>=from_at),
 environment_kind text NOT NULL CHECK(environment_kind IN ('FIXTURE','INSTITUTION_TEST','PRODUCTION')),
 environment_id text NOT NULL, result jsonb NOT NULL CHECK(jsonb_typeof(result)='object'),
 computed_at timestamptz NOT NULL,
 FOREIGN KEY(tenant_id,scope_id) REFERENCES config_scopes(tenant_id,id),
 FOREIGN KEY(tenant_id,definition_configuration_id) REFERENCES configuration_revisions(tenant_id,id)
);

-- Append-only audit enforcement; runtime roles must also be denied UPDATE/DELETE/TRUNCATE.
-- Schema owner/admin authority remains an external operational control; hash != certification.
CREATE FUNCTION rmw_reject_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 RAISE EXCEPTION 'audit_events is append-only';
END;
$$;
CREATE TRIGGER rmw_audit_no_update_delete BEFORE UPDATE OR DELETE ON audit_events
 FOR EACH ROW EXECUTE FUNCTION rmw_reject_audit_mutation();
CREATE TRIGGER rmw_audit_no_truncate BEFORE TRUNCATE ON audit_events
 FOR EACH STATEMENT EXECUTE FUNCTION rmw_reject_audit_mutation();

-- No default tenant, demo user, pilot enable, synthetic business threshold, provider
-- configuration or ownership backfill is inserted. Seed only explicitly isolated test DBs.
COMMIT;
